function GeoProvincePage() {
  const [metric, setMetric] = useState("ROAS");
  const [selected, setSelected] = useState(geoProvinces[0]);
  const [compare, setCompare] = useState<typeof geoProvinces[number] | null>(null);
  const [hovered, setHovered] = useState<typeof geoProvinces[number] | null>(null);
  const [tab, setTab] = useState("Campaigns");
  const metrics = ["Spend", "CTR", "CPA", "CPM", "Registrations", "Deposit Success", "Revenue", "ROAS", "Customer Quality"];
  const metricValue = (item: typeof geoProvinces[number]) => metric === "ROAS" ? item.roas : metric === "CTR" ? item.ctr : metric === "CPA" ? item.cpa : metric === "Deposit Success" ? item.deposits : metric === "Revenue" ? item.revenue : metric === "Customer Quality" ? `${item.opportunity}/100` : metric === "Spend" ? item.spend : item.impressions;
  const sorted = [...geoProvinces].sort((a,b) => metricValue(b).localeCompare(metricValue(a), undefined, { numeric: true }));
  const selectProvince = (item: typeof geoProvinces[number]) => { setSelected(item); if (compare && compare.name === item.name) setCompare(geoProvinces.find(candidate => candidate.name !== item.name) || null); setTab("Campaigns"); };
  return <PageShell eyebrow="MARKETING ANALYTICS · GEO จังหวัด" title="ผลลัพธ์โฆษณาแยกตามจังหวัด" description="วิเคราะห์ Spend, Conversion และ Customer Quality ตามภูมิศาสตร์ พร้อม Drill-down ไปยัง Campaign, Creative, Audience, Funnel และ Event.">
    <div className="geo-status-bar"><div><span className="kpi-icon amber"><MapPinned size={17} /></span><div><strong>GEO Performance Console</strong><small>Northstar Commerce · 18 จังหวัดที่มีข้อมูล · อัปเดตทุก 30 นาที</small></div></div><span className="analysis-prototype-badge">DEMO ANALYTICS · SIMULATION</span></div>
    <div className="geo-toolbar"><div className="geo-metric-switcher">{metrics.map(item => <button key={item} className={metric === item ? "active" : ""} onClick={() => setMetric(item)}>{item}</button>)}</div><div className="geo-toolbar-actions"><span className="analysis-prototype-badge">SAMPLE DATA</span><button className="secondary-button" onClick={() => setCompare(compare ? null : (selected.name === geoProvinces[1].name ? geoProvinces[0] : geoProvinces[1]))}><GitBranch size={14} /> {compare ? "ปิด Compare" : "Compare Provinces"}</button></div></div>
    <div className="geo-layout"><section className="panel geo-map-panel"><div className="panel-heading"><div><div className="section-kicker">PROVINCE MAP · CHOROPLETH</div><h2>{metric} intensity</h2></div><span className="live-label">HOVER / CLICK</span></div><div className="geo-map-stage"><div className="geo-map-silhouette" aria-label="แผนที่ประเทศไทยแบบจำลอง">{geoProvinces.map((item,index) => <button key={item.name} className={`province-cell ${item.color} p${index} ${selected.name === item.name ? "selected" : ""}`} onMouseEnter={() => setHovered(item)} onMouseLeave={() => setHovered(null)} onClick={() => selectProvince(item)}><span>{item.name}</span><b>{metricValue(item)}</b></button>)}</div>{hovered && <div className="geo-tooltip"><strong>{hovered.name}</strong><span>{metric}: {metricValue(hovered)}</span><small>คลิกเพื่อดูรายละเอียดจังหวัด</small></div>}<div className="geo-map-legend"><span>ต่ำ</span><i className="legend-low" /><i className="legend-mid" /><i className="legend-high" /><span>สูง</span></div></div><div className="geo-map-note"><ShieldCheck size={14} /><span>ข้อมูล Aggregated เท่านั้น · จังหวัดที่มีจำนวน Event ต่ำกว่า Minimum Threshold จะแสดงเป็น No Data</span></div></section><aside className="panel province-panel"><div className="panel-heading"><div><div className="section-kicker">PROVINCE DRILL-DOWN</div><h2>{selected.name}</h2><small className="province-region">{selected.region}</small></div><button className="more-button"><MoreHorizontal size={17} /></button></div><div className="province-kpi-grid"><div><small>Spend</small><strong>{selected.spend}</strong></div><div><small>Revenue</small><strong>{selected.revenue}</strong></div><div><small>ROAS</small><strong className="cyan-text">{selected.roas}</strong></div><div><small>Deposit Success</small><strong>{selected.deposits}</strong></div><div><small>CTR</small><strong>{selected.ctr}</strong></div><div><small>CPA</small><strong>{selected.cpa}</strong></div><div><small>Frequency</small><strong>{selected.frequency}</strong></div><div><small>Opportunity</small><strong className="amber-text">{selected.opportunity}/100</strong></div></div><div className="province-trend"><div><span className="section-kicker">7-DAY TREND</span><strong>+18.4%</strong></div><div className="mini-bars">{[42,55,48,67,61,78,90].map((height,i)=><i key={i} style={{height:`${height}%`}} />)}</div></div><div className="geo-tabs">{["Campaigns","Creatives","Audience","Funnel","Events","AI Insight"].map(item=><button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === "Campaigns" && <div className="geo-related-list">{[["Q3 Deposit · Broad","cmp_q3_deposit","5.20x"],["High-value Lookalike 1%","cmp_high_value_lal","4.84x"],["Retarget · Registered","cmp_retarget_reg","4.12x"]].map(item=><button key={item[1]}><span><strong>{item[0]}</strong><small>{item[1]}</small></span><b>{item[2]}</b><ArrowUpRight size={12} /></button>)}</div>}{tab === "Creatives" && <div className="geo-related-list">{[[selected.creative,"Video / Creative proof","4.8% CTR"],["ad_carousel_02","Carousel / Benefits","3.9% CTR"],["ad_static_05","Static / Trust","2.8% CTR"]].map(item=><button key={item[0]}><span><strong>{item[0]}</strong><small>{item[1]}</small></span><b>{item[2]}</b><ArrowUpRight size={12} /></button>)}</div>}{tab === "Audience" && <div className="geo-related-list">{[["High Value Prospects","12.8% deposit rate"],["Repeat Depositors","9.4% deposit rate"],["Qualified Leads","6.2% deposit rate"]].map(item=><button key={item[0]}><span><strong>{item[0]}</strong><small>Audience Insight</small></span><b>{item[1]}</b><ArrowUpRight size={12} /></button>)}</div>}{tab === "Funnel" && <div className="geo-funnel-list">{[["Ad Click","18,420","100%"],["Registration","1,286","6.9%"],["Deposit Pending","224","17.4%"],["Deposit Success","118","52.7%"]].map(item=><div key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong><b>{item[2]}</b></div>)}</div>}{tab === "Events" && <div className="geo-related-list">{[["evt_01JXYZ123","Deposit Success","usr_123456 · ฿1,500"],["evt_01JXYA224","Registration Completed","usr_987654"],["evt_01JXYB891","Repeat Deposit","usr_123456 · ฿3,200"]].map(item=><button key={item[0]}><span><strong>{item[0]}</strong><small>{item[1]}</small></span><b>{item[2]}</b><ArrowUpRight size={12} /></button>)}</div>}{tab === "AI Insight" && <div className="geo-ai-insight"><Sparkles size={17} /><strong>{selected.name} มี Opportunity สูงกว่าค่าเฉลี่ย 21%</strong><p>CTR สูงและ ROAS แข็งแรง แต่มีสัดส่วน Repeat Deposit ต่ำกว่า Benchmark 8% แนะนำตรวจ Audience และช่วงเวลา 20:00–23:00 ก่อนเพิ่มงบใน Simulation</p><button className="secondary-button">ดู Evidence <ArrowUpRight size={13} /></button></div>}</aside></div>
    {compare && <section className="panel geo-compare-panel"><div className="panel-heading"><div><div className="section-kicker">COMPARE PROVINCES</div><h2>{selected.name} vs {compare.name}</h2></div><span className="analysis-badge cyan">SIDE BY SIDE</span></div><div className="compare-grid">{[["ROAS",selected.roas,compare.roas],["CTR",selected.ctr,compare.ctr],["CPA",selected.cpa,compare.cpa],["Deposit Success",selected.deposits,compare.deposits],["Opportunity",`${selected.opportunity}/100`,`${compare.opportunity}/100`]].map(row=><div key={row[0]}><span>{row[0]}</span><strong>{row[1]}</strong><strong>{row[2]}</strong><small>{row[1] === row[2] ? "เท่ากัน" : "แตกต่างตาม Demo Dataset"}</small></div>)}</div></section>}
    <section className="panel geo-ranking-panel"><div className="panel-heading"><div><div className="section-kicker">PROVINCE RANKING</div><h2>จัดอันดับตาม {metric}</h2></div><span className="live-label">{sorted.length} PROVINCES</span></div><div className="geo-ranking-table"><div className="geo-ranking-head"><span>#</span><span>PROVINCE</span><span>REGION</span><span>{metric}</span><span>OPPORTUNITY</span></div>{sorted.map((item,index)=><button key={item.name} className={selected.name === item.name ? "selected" : ""} onClick={() => selectProvince(item)}><span>{String(index + 1).padStart(2,"0")}</span><strong>{item.name}</strong><span>{item.region}</span><b>{metricValue(item)}</b><em>{item.opportunity}/100</em></button>)}</div></section>
    <div className="analysis-doc-panel"><div className="analysis-doc-icon"><MapPinned size={18} /></div><div><div className="section-kicker">GEO GUIDE</div><h2>การใช้งานเมนูนี้</h2><p>เลือก Metric เพื่อเปลี่ยนสี Map และ Ranking จากนั้น Hover หรือ Click จังหวัดเพื่อดู KPI, Campaign, Creative, Audience, Funnel, Event และ AI Insight โดยทุกข้อมูลเป็น Demo Analytics</p></div><span className="analysis-prototype-badge">NO PRODUCTION API</span></div>
  </PageShell>;
}

